        'story.event.ep07.dialogue.02': '그렇다. 여기까지 살아온 것은 칭찬하마. 하지만 네 여정은 여기서 끝난다.',
        'story.event.ep07.dialogue.03': '싸움이 끝난 뒤에도 같은 말을 할 수 있는지 보겠다. 하겐, 곧 구해드리겠습니다.',
