        'story.event.ep08.focus.ship': '해적선',
        'story.event.ep08.dialogue.01': '이 배가 시시리오 섬으로 갈 수 있는 유일한 배인 모양입니다.',
        'story.event.ep08.dialogue.02': '좋군. 오늘은 제법 큰돈을 벌 수 있겠어.',
        'story.event.ep08.dialogue.03': '당신이 이 배의 두목입니까?',
        'story.event.ep08.dialogue.04': '두목은 없다. 버림받은 사람들이 이 배에서 함께 살아갈 뿐이지.',
        'story.event.ep08.dialogue.05': '내 목적은 하나뿐입니다. 이 배를 타고 바다를 건너야 합니다.',
        'story.event.ep08.dialogue.06': '그럴 힘이 있는지 확인해 보겠다. 덤벼라!',
        'story.event.ep08.combatStart': '승리조건 : 해적두목 셔트의 처치',
