        'story.event.ep09.focus.coast': '시시리오섬 해안',
        'story.event.ep09.focus.dangu': '단구의 매복 지점',
        'story.event.ep09.dialogue.01': '여기만 지나면 두 번째 봉인이 있는 곳일까요? 평범한 섬처럼 보입니다.',
        'story.event.ep09.dialogue.02': '몬스터가 상당히 많습니다.',
        'story.event.ep09.dialogue.03': '그래도 섬 안으로 들어가는 길은 여기뿐입니다. 저들을 뚫어야 합니다.',
        'story.event.ep09.dialogue.04': '설마 여기까지 올 줄이야. 그분이 너를 예의주시한 것도 당연하군.',
        'story.event.ep09.dialogue.05': '넌 누구냐.',
        'story.event.ep09.dialogue.06': '나는 너를 저승으로 보낼 사자다. 나를 만나기 전에 내 부하들부터 상대해 봐라.',
        'story.event.ep09.combatStart': '승리조건 : 단구의 처치',
