        'story.event.ep10.focus.naiad': '나이아드의 호수 중앙',
        'story.event.ep10.dialogue.01': '호수의 물빛이 너무도 화려하고 아름답습니다.',
        'story.event.ep10.dialogue.02': '이곳은 미움과 유혹의 봉인입니다. 나이아드의 계책에 흔들리지 마십시오.',
        'story.event.ep10.dialogue.03': '제법 똑똑한 참모를 데리고 다니는구나. 긴 여행에 지쳤을 텐데 쉬어가지 않겠느냐?',
        'story.event.ep10.dialogue.04': '시끄럽다. 네 간교한 말에 넘어갈 것 같으냐?',
        'story.event.ep10.dialogue.05': '그래? 이 아름다운 세상을 실컷 구경해 두거라. 호호호!',
        'story.event.ep10.combatStart': '승리조건 : 나이아드의 처치',
        'story.event.ep10.fiancee.marker': '트리파니의 약혼녀',
