        'story.event.ep11.focus.oasis': '아케론 오아시스',
        'story.event.ep11.focus.charon': '카론의 매복 지점',
        'story.event.ep11.dialogue.01': '이곳이 세번째 봉인이군. 하겐에게 듣기론 분명히 진실의 봉인이라 들었는데..',
        'story.event.ep11.dialogue.02': '천년만에 나의 잠을 깨는 자가 누구인가..',
        'story.event.ep11.dialogue.03': '너는 또 무슨 몬스터냐?!',
        'story.event.ep11.dialogue.04': '몬스터? 나를 몬스터 같은 하류 계급으로 보다니...',
        'story.event.ep11.dialogue.05': '그럼 수많은 사람을 살생하고 있으면서 무엇으로 불리길 원하느냐?!',
        'story.event.ep11.dialogue.06': '두번째 봉인을 풀었다기에 좀 다르게 보았건만.. 네가 원하는 대답은 나를 이기면 나올 것이다.',
        'story.event.ep11.combatStart': '승리조건 : 카론의 처치',
        'story.event.ep11.chest.marker': '오아시스 상자',
