        'story.event.ep12.focus.approach': '피라미드 진입로',
        'story.event.ep12.focus.mantagoras': '만타고라스의 무덤 입구',
        'story.event.ep12.focus.advance': '아멘호텝 왕의 무덤 앞',
        'story.event.ep12.dialogue.01': '피닉스를 보고 사람이 얼마나 잔인해질 수 있는가를 알 수 있었다. 앞으로 가야할 곳 역시 이렇단 말인가.',
        'story.event.ep12.dialogue.02': '아멘호텝 왕의 무덤에 들어가려는 자가 누구인가..',
        'story.event.ep12.dialogue.03': '나는 봉인을 닫으려고 온 용사이다.',
        'story.event.ep12.dialogue.04': '그러려면 먼저 나를 통과하여야만 할 텐데 그럴 자신이 있는가?',
        'story.event.ep12.dialogue.05': '그건 해봐야 알겠지.',
        'story.event.ep12.combatStart': '승리조건 : 만타고라스의 처치',
