        'story.event.ep12.enemyDefeat.650': '으으..',
        'story.event.ep12.enemyDefeat.710': '으악 또 당했다..',
        'story.event.ep12.enemyDefeat.720': '나중에 또 나오고 말거야. 힝~',
        'story.event.ep12.enemyDefeat.730': '내 뒤에 있는 놈은 조심해야 할 껄..',
        'story.event.ep12.bossDefeat.01': '과연 택자 답군. 나를 이겼으니 무덤안으로 들어가도록 해라.',
        'story.event.ep12.bossDefeat.02': '왜 스핑크스가 요괴로 변하여 이곳을 지키고 있던 것인가?',
        'story.event.ep12.bossDefeat.03': '왕이나 귀족 등 탐욕의 무리들이 자신들을 저주하는 백성들로부터 자기를 지키기 위해 나를 이렇게 만들어 놓았네. 죽은 영혼들마저 자신의 노예로 삼기위해서 말이지...',
        'story.event.ep12.bossDefeat.04': '김세스의 아내는 어떻게 되었나?',
        'story.event.ep12.bossDefeat.05': '그녀는 이미 미이라들이 영생의 제물로 쓰기 위해 무덤 안으로 데리고 갔다.',
        'story.event.ep12.bossDefeat.06': '뭐라고? 어서 서둘러야겠군!',
        'story.event.ep12.bossDefeat.07': '잠깐! 그녀를 구하기 위해서는 무덤 안의 마물들을 하나도 남김 없이 처리해야 한다. 나를 이긴 상으로 가르쳐 주는 것이다.',
        'story.event.ep12.tomb.result': '아멘호텝 왕의 무덤으로 가는 길이 열렸습니다.',
        'story.event.ep12.objective': '시나리오 클리어',
        'story.event.ep13.focus.entry': '피라미드 내부 입구',
        'story.event.ep13.focus.myant': '미얀트의 석실',
        'story.event.ep13.dialogue.01': '여기가 세번째 봉인의 마지막 관문이다. 그러나 일반 왕의 무덤과 다른 것이 없지 않은가..',
        'story.event.ep13.dialogue.02': '여기까지 들어올 수가 있었다니..... 과연 아흐리만께서 주의하라 할 만하군.',
        'story.event.ep13.dialogue.03': '아흐리만? 그럼 네가 원혼들이 하늘로 올라가는 것을 방해한 몬스터인가?',
        'story.event.ep13.dialogue.04': '방해는 아니지. 그들은 위대한 아흐리만께서 이 제국을 차지하는 데 있어 영광의 제물이 된 것이니 감사해야 할 것이다.',
        'story.event.ep13.dialogue.05': '뭣이.... 그것을 말이라고 하고 있는가? 내 당장 너를 응징하리라..',
        'story.event.ep13.combatStart': '승리조건 : 미얀트의 처치',
        'story.event.ep13.trap.marker': '왕묘 함정',
        'story.event.ep13.trap.50': '적의 함정이군.',
        'story.event.ep13.trap.51': '이런! 함정이다!',
        'story.event.ep13.trap.52': '앗! 함정.......',
        'story.event.ep13.trap.53': '적의 함정이군.',
        'story.event.ep13.trap.54': '앗! 함정.......',
        'story.event.ep13.trap.55': '우와아아......악!',
        'story.event.ep13.trap.56': '앗! 함정.......',
        'story.event.ep13.trap.57': '적의 함정이군.',
