        'story.event.ep13.chest.healPotion': '힐포션을 얻었습니다.',
        'story.event.ep13.chest.magicPotion': '매직포션을 얻었습니다.',
        'story.event.ep13.thirdSeal.result': '세번째 봉인의 마지막 관문을 돌파했습니다.',
        'story.event.ep13.objective': '시나리오 클리어',
        'story.event.ep14.focus.arrival': '스케리아 남쪽 입구',
        'story.event.ep14.focus.descendant': '스케리아의 신족 후예',
        'story.event.ep14.dialogue.01': '사막의 싸움으로 인하여 부하들이 탈진해 있고 무기마저 떨어졌군. 여기서 부족한 것을 보충해야만 하겠다. 그런데 분위기가 이상하군..',
        'story.event.ep14.dialogue.02': '당신이 제3의 봉인까지 닫으신 용사분 맞는지요.',
        'story.event.ep14.dialogue.03': '그렇소만 당신은?',
        'story.event.ep14.dialogue.04': '여기는 스케리아란 곳으로 신족의 후예만이 살고 있는 곳입니다. 그런데 봉인이 깨지면서 몬스터들이 여기를 점령했습니다.',
        'story.event.ep14.dialogue.05': '여기를요? 그러나 별로 이상한 것은 모르겠는데.....',
        'story.event.ep14.dialogue.06': '당신이 오신다는 말을 듣고 조용한 것입니다. 덕분에 저도 당신에게 말을 할 수 있구요. 제발 도와 주십시오.',
        'story.event.ep14.dialogue.07': '무엇을 말입니까?',
        'story.event.ep14.dialogue.08': '이곳에는 야두아라는 약초가 있습니다. 병자의 회복과 상처의 치료에 놀라운 효과가 있지만 일 년에 한 뿌리 정도밖에 구할 수 없는 희귀한 약초입니다. 만약 그것이 몬스터의 손에 들어가면 그들의 힘은 더욱 더 강해질 것입니다. 제발 야두아를 지켜주십시오.',
        'story.event.ep14.dialogue.09': '알겠습니다. 제가 할 수 있는 힘을 다해 그 약초를 지키겠습니다.',
        'story.event.ep14.combatStart': '승리조건 : 셔트의 처치',
