        'story.event.ep15.dialogue.01': '비공정이 다시 올 때까지 무기도 비축하고 휴식도 취해야겠습니다.',
        'story.event.ep15.dialogue.02': '휴식이 필요하긴 한데, 마을이 어째 좀 이상한 것 같습니다.',
