        'story.event.ep15.dialogue.05': '휴~ 하마터면 당할 뻔했군.',
        'story.event.ep15.dialogue.06': '이 정도야 몸을 푸는 정도로 생각하겠습니다. 가봅시다.',
        'story.event.ep15.combatStart': '승리조건 : 마기의 처치',
        'story.event.ep15.villager.marker': '이름없는 마을 주민',
        'story.event.ep15.villager.01': '안녕하시오. 난 이 마을의 주민이었지.. 그런데 어느 날부터 마을 사람들이 변해가고 있소. 하지만 아직 괜찮은 사람들이 있으니 많이 도움을 줄 것이오.',
        'story.event.ep15.villager.02': '거 이상한 현상이군. 난 바빠서 이만 가봐야겠소.',
        'story.event.ep15.villager.03': '잠깐 한 가지 힌트를 드리겠소. 마을 곳곳에 피어 있는 꽃은 여러 가지 아이템을 만들 수 있는 재료입니다. 구하셔서 마을의 주술사에게 가져다주면 아주 귀한 아이템을 줄 것이오. 하지만 어떤 꽃은 독이 있으니 조심하시오.',
        'story.event.ep15.villager.04': '고맙소.. 아참 한 가지 물어볼 게 있는데 이 마을에 좋은 무기상점이 있다고 들었는데 거기가 어딘지 아시오?',
        'story.event.ep15.villager.05': '마을이 변하면서부터 좋은 무기들도 모두 같이 없어졌다오.',
        'story.event.ep15.villager.06': '아무튼 고맙소. 몸조심하시오.',
        'story.event.ep15.sign.marker': '마을 표지판',
        'story.event.ep15.sign.mineWarning': '여기는 이름없는 마을입니다. 옛날 전쟁터였던 곳이라 길이 아닌 곳에는 지뢰가 있을 수 있습니다. 조심하세요.',
        'story.event.ep15.sign.treasureHint': '오른쪽 맨 위에 있는 나무에서 오른쪽으로 8칸에 보물이 묻혀 있습니다. 하지만 주위에 함정이 도사리고 있으니 조심하십시오.',
        'story.event.ep15.sign.joke': '여기까지 오시느라 수고하셨습니다. 이 표지판은 썰렁~',
