        'story.event.ep16.dialogue.02': '나를 앞에 두고 비공정으로 가려 하다니... 비공정이 아니라 저승으로 가게 해주마.',
        'story.event.ep16.dialogue.03': '네놈은 누구냐?',
        'story.event.ep16.dialogue.04': '비공정을 지키는 바르바투를 모른단 말인가? 하찮은 인간 주제에 악마에게 대항하다니. 너는 내 이름을 알게 된 것만으로도 영광인 줄 알아라.',
