        'story.event.ep17.dialogue.01': '드디어 마지막 관문까지 왔다. 과연 나는 비공정에게 선택 받을 수 있을까. 만약 여기서 선택이 안 된다면 나는 헛수고만 한 것이 아닌가....',
        'story.event.ep17.dialogue.02': '나약한 마음을 가지면 안 됩니다. 이 세계의 운명이 당신의 어깨 위에 달려 있습니다.',
        'story.event.ep17.dialogue.03': '압니다. 하지만 의심이 생기는군요....',
        'story.event.ep17.dialogue.04': '여기는 순수의 봉인입니다. 인간이 순수하지 못할 경우 당신은 이미 패자가 될 것입니다.',
        'story.event.ep17.dialogue.05': '알겠습니다. 끝까지 최선을 다하겠습니다. 아니 내가 택자라는 믿음을 가지고 가겠습니다.',
