        'story.event.ep18.dialogue.01': '드디어 아멘트로군. 과연 여기에서 군터를 찾을 수 있을까?',
        'story.event.ep18.dialogue.02': '여기까지 잘도 왔구나... 하지만 이제 이곳이 너의 무덤이 될 것이다.',
        'story.event.ep18.dialogue.03': '누구 명이 다한 것인지는 해봐야 아는 법. 죽기 전에 기도나 해라!',
        'story.event.ep18.dialogue.04': '크하하하 내 너의 목을 베어 새로운 세계를 여는 제물로 삼으리라!!!',
