        'story.event.ep19.dialogue.01': '드디어 성 내부로 들어왔군. 아니 그런데 여긴 왜 이리 한기가 도는 것일까? 몸이 얼어붙을 것만 같아!!! 여기엔 진짜 군터가 있을까? 아니면 또 다른 졸개가 기다리고 있는 것일까?...',
        'story.event.ep19.dialogue.02': "졸개라니! 감히 인간따위가! 그건 그렇고 과연 '그 분'이 인정할 만하구나. 여기까지 들어올 수 있을 줄이야.",
        'story.event.ep19.dialogue.03': '너희들은 또 누구냐? 군터냐? 아님 또 그저 졸개에 불과한 것이냐?',
        'story.event.ep19.dialogue.04': '그건 우리를 이기면 저절로 알게 될 것이다.. 물론 할 수 있다면 말이지.',
