        'story.event.ep20.dialogue.04': '군터는 나를 이곳에 불러낸 역할에 불과할 뿐 아무것도 아니다.',
        'story.event.ep20.dialogue.05': '겁장이 같으니라고 이제서야 제 모습을 나타냈군.',
        'story.event.ep20.dialogue.06': '나를 겁장이라고 말하는 자가 있다니... 크하하하. 이제서야 나타난 건 너를 처리하는데 나까지 등장할 필요가 없다고 느꼈었을 뿐이었고, 이제 더 이상의 시간 낭비가 필요 없다고 여겨져 내 친히 나온 것에 불과할 뿐이다. 내 손에 죽는 것만으로도 너는 영광으로 알아야 할 것이다.',
        'story.event.ep20.dialogue.07': '못난 것들.. 너희들은 이만 가거라..!',
        'story.event.ep20.dialogue.08': '사악한 놈. 아무리 마족이라 해도 자기 부하들을 죽이다니.... 내 필히 너를 응징하리라!',
        'story.event.ep20.dialogue.09': '나의 분신들을 상대한 후에 이야기하도록 하지... 하하하하....',
        'story.event.ep20.dialogue.10': '흥! 건방진 놈! 감히 인간 주제에 나에게 설교를 하다니.. 죽음으로 그 죄를 씻어라!!! 으하하하하하',
        'story.event.ep20.combatStart': '승리조건 : 메피스토펠레스의 처치와 암흑의 검 회수',
        'story.event.ep20.trap.marker': '아멘트 번개 함정',
        'story.event.ep20.trap.53': '아니 저것은!!! 으악!',
        'story.event.ep20.cache.marker': '아멘트 2층 보물',
