        'story.event.ep21.focus.summoningHall': '네르갈 성 소환진',
        'story.event.ep21.focus.nergal': '네르갈',
        'story.event.ep21.focus.fourKings': '지옥의 사천왕',
        'story.event.ep21.dialogue.01': '드디어 나타났구나 택자여.. 그러나 나 역시 준비를 해 두었다.',
        'story.event.ep21.dialogue.02': '나오너라! 지옥의 사천왕!',
        'story.event.ep21.dialogue.03': '우리들을 부른 것이 너인가..?',
        'story.event.ep21.dialogue.04': '그렇다. 너희들은 소환자인 나의 명령에 따라야 한다. 너희들은 지금부터 각각 나의 4개 성에 가서 택자를 맞아 싸우도록 해라.',
        'story.event.ep21.dialogue.05': '가거라!',
        'story.event.ep21.dialogue.06': '택자는 반드시 이곳으로... 그의 힘이 어느정도인가.. 궁금해지는군...',
        'story.event.ep21.combatStart': '승리조건 : 네르갈의 처치',
        'story.event.ep21.cache.marker': '네르갈 성 유물',
