        'story.event.ep21.cache.valkyrie': '발키리를 얻었습니다.',
        'story.event.ep21.cache.bernium': '베르니움을 얻었습니다.',
        'story.event.ep21.cache.finalRelic': '이니그마 블레이드를 얻었습니다.',
        'story.event.ep21.objective': '시나리오 클리어',
        'story.event.ep21.fourKings.succubus': '서큐버스',
        'story.event.ep21.fourKings.beramode': '베라모드',
